const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();
    const K = BigInt(nextInt());

    const a_spells = new Array(N);
    for (let i = 0; i < N; i++) a_spells[i] = BigInt(nextInt());

    const b_spells = new Array(N);
    for (let i = 0; i < N; i++) b_spells[i] = BigInt(nextInt());

    const a_meals = new Array(M);
    for (let i = 0; i < M; i++) a_meals[i] = BigInt(nextInt());

    const b_meals = new Array(M);
    for (let i = 0; i < M; i++) b_meals[i] = BigInt(nextInt());

    const Q = nextInt();
    const queries = new Array(Q);
    for (let i = 0; i < Q; i++) queries[i] = BigInt(nextInt());

    const MOD = 1000000007n;

    // 1. Processar e ordenar as refeições
    // Refeição u=(a1, b1) deve vir antes de v=(a2, b2) se b1*(a2 - 1) > b2*(a1 - 1)
    const meals = new Array(M);
    for (let i = 0; i < M; i++) {
        meals[i] = { a: a_meals[i], b: b_meals[i] };
    }

    meals.sort((u, v) => {
        const val1 = u.b * (v.a - 1n);
        const val2 = v.b * (u.a - 1n);
        if (val1 > val2) return -1;
        if (val1 < val2) return 1;
        return 0;
    });

    let A_meal = 1n;
    let B_meal = 0n;
    for (let i = 0; i < M; i++) {
        A_meal = (A_meal * meals[i].a) % MOD;
        B_meal = (B_meal * meals[i].a + meals[i].b) % MOD;
    }

    // 2. Construir a Envoltória Convexa Superior (CHT) para os feitiços
    const spells = new Array(N);
    for (let i = 0; i < N; i++) {
        spells[i] = { a: a_spells[i], b: b_spells[i] };
    }

    // Ordenar por a crescente; se empate, por b decrescente
    spells.sort((u, v) => {
        if (u.a < v.a) return -1;
        if (u.a > v.a) return 1;
        if (u.b > v.b) return -1;
        if (u.b < v.b) return 1;
        return 0;
    });

    // Manter apenas o maior b para cada a
    const uniqueSpells = [];
    for (let i = 0; i < N; i++) {
        if (i === 0 || spells[i].a !== spells[i - 1].a) {
            uniqueSpells.push(spells[i]);
        }
    }

    // Construção do Hull
    const hull = [];
    for (let i = 0; i < uniqueSpells.length; i++) {
        const L = uniqueSpells[i];
        while (hull.length >= 2) {
            const L1 = hull[hull.length - 2];
            const L2 = hull[hull.length - 1];
            // x_int(L2, L) <= x_int(L1, L2)
            // (L2.b - L.b) / (L.a - L2.a) <= (L1.b - L2.b) / (L2.a - L1.a)
            if ((L2.b - L.b) * (L2.a - L1.a) <= (L1.b - L2.b) * (L.a - L2.a)) {
                hull.pop();
            } else {
                break;
            }
        }
        hull.push(L);
    }

    // Calcular pontos de transição t[i]
    // Para y >= t[i], a reta hull[i] é >= hull[i-1]
    const H = hull.length;
    const t = new Array(H);
    t[0] = 1n;
    for (let i = 1; i < H; i++) {
        const L_prev = hull[i - 1];
        const L_curr = hull[i];
        const num = L_prev.b - L_curr.b;
        const den = L_curr.a - L_prev.a;
        if (num <= 0n) {
            t[i] = 1n;
        } else {
            // ceil(num / den) = (num + den - 1) / den
            t[i] = (num + den - 1n) / den;
            if (t[i] < 1n) t[i] = 1n;
        }
    }

    function power(base, exp) {
        let res = 1n;
        base = base % MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    function modInverse(n) {
        return power(n, MOD - 2n);
    }

    const lastSpell = hull[H - 1];
    const t_last = t[H - 1];

    let out = [];
    for (let q = 0; q < Q; q++) {
        let y = queries[q];
        let rem = K;

        while (rem > 0n) {
            // Se já alcançamos a região onde a última reta (maior inclinação) domina:
            if (y >= t_last) {
                const A = lastSpell.a;
                const B = lastSpell.b;
                if (A === 1n) {
                    y = (y + (rem % MOD) * (B % MOD)) % MOD;
                } else {
                    const A_pow = power(A, rem);
                    const frac = ((A_pow - 1n + MOD) % MOD * modInverse(A - 1n)) % MOD;
                    const term2 = ((B % MOD) * frac) % MOD;
                    y = (A_pow * (y % MOD) + term2) % MOD;
                }
                rem = 0n;
                break;
            }

            // Busca binária para encontrar a melhor reta no estado atual
            let low = 0, high = H - 1, best = 0;
            while (low <= high) {
                const mid = (low + high) >> 1;
                if (t[mid] <= y) {
                    best = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            const chosen = hull[best];
            y = chosen.a * y + chosen.b;
            rem -= 1n;
        }

        y = y % MOD;
        const ans = (A_meal * y + B_meal) % MOD;
        out.push(ans.toString());

        if (out.length >= 10000) {
            process.stdout.write(out.join('\n') + '\n');
            out = [];
        }
    }

    if (out.length > 0) {
        process.stdout.write(out.join('\n') + '\n');
    }
}

